sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var value = g_form.getValue('deposit_amount');

    if (isNaN(value) || value === '' || value === null) {
        g_form.showFieldMsg('deposit_amount', 'Please enter a valid numeric value.', 'error');
        // g_form.setValue('deposit_amount', '');
    } else if (parseFloat(value) < 0) {
        g_form.showFieldMsg('deposit_amount', 'Value cannot be less than zero.', 'error');
        // g_form.setValue('deposit_amount', '');
    }

}
